-- [Deepthinking]
CREATE TEMPORARY VIEW ods_llm_deepthinking_${grass_region_without_quote} AS
SELECT
    search_session_id
    ,request_id AS srp_request_id
    ,TRANSFORM(FROM_JSON(keyword_extraction, 'ARRAY<ARRAY<STRING>>'), x -> x[0]) AS llm_keyword_extraction
    ,llm_user_profile
    ,demand_analysis AS llm_demand_analysis
    ,FROM_JSON(filter_and_sorted_items, 'ARRAY<STRUCT<item_id:BIGINT,shop_id:BIGINT,search_query:STRING>>') AS llm_item_list
FROM
    srdi_mart.ods_sr_data_warehouse_search_llm_deepthinking_recall__reg_continuous_s0_live a
JOIN
    srdi_mart.dwd_sr_data_warehouse_search b
ON
    GET_JSON_OBJECT(a.req_data, '$.request_id') = b.request_id
WHERE
    a.dt IN (CAST(DATE_SUB(${local_date}, 1) AS STRING), ${local_date}, CAST(DATE_ADD(${local_date}, 1) AS STRING))
    AND DATE(date_timezone_convert(dt,hour,'SG',${grass_region},"yyyy-MM-dd")) = ${local_date}
    AND GET_JSON_OBJECT(a.req_data, '$.region') = ${grass_region}
    AND b.grass_region = ${grass_region}
    AND b.local_date = ${local_date}
    AND b.page_type IN ('global_search','search_in_pdp','search_prefill')
    AND b.user_id > 0
GROUP BY
    1,2,3,4,5,6;

--sql_divide_splitter--
-- [Autocomplete]
CREATE TEMPORARY VIEW autocomplete_click_${grass_region_without_quote} AS
SELECT
    event_id
    ,hint_keyword_source
FROM
    srdi_mart.dwd_sr_data_warehouse_search
WHERE 
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND user_id > 0
    AND page_type = 'search_suggest_page'
    AND page_section[0] = 'search_bar'
    AND target_type = 'hint_keyword'
    AND operation = 'click'
    AND original_operation = 'click'
    AND hint_keyword_source IN (18, 19)
GROUP BY
    1,2;

--sql_divide_splitter--

CREATE TEMPORARY VIEW search_mapped_page_types_${grass_region_without_quote} AS
SELECT
    mapped_page_type
FROM
    mp_foa.dim_search_domain_map__reg_live
WHERE 
    grass_region = ${grass_region}
    AND grass_date = DATE_SUB(${local_date}, 1);

--sql_divide_splitter--

CREATE TEMPORARY VIEW autocomplete_filter_${grass_region_without_quote} AS
SELECT
    search_session_id
    ,MAX(b.hint_keyword_source) AS autocomplete_queue
FROM
    srdi_mart.dwd_sr_data_warehouse_platform a
JOIN
    autocomplete_click_${grass_region_without_quote} b
ON
    a.pre_source_event_id = b.event_id
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND user_id > 0
    AND page_type IN (SELECT mapped_page_type FROM search_mapped_page_types_${grass_region_without_quote})
    AND page_section IS NULL
    AND operation = 'view'
GROUP BY
    1;

