-- Shared dwd_platform query for all features
CREATE TEMPORARY VIEW dwd_data_${grass_region_without_quote} AS
SELECT
    user_id
    ,request_id AS srp_request_id
    ,item_id
    ,page_type
    ,page_section[0] AS page_section
    ,target_type
    ,is_ads
    ,location AS srp_location
    ,global_session_id
    ,search_session_id
    ,keyword
    ,COALESCE(is_llm_deepthinking, FALSE) AS is_llm_deepthinking
    ,COALESCE(ARRAY_CONTAINS(TRANSFORM(search_filter_string, x -> FROM_JSON(x,'STRUCT<filter_type:INT>').filter_type), 3), FALSE) AS is_llm_filtered
    ,search_filter_string
    ,COALESCE(rs_is_llm_card, FALSE) AS rs_is_llm_card
    ,rs_clicked_keyword AS fe_module_clicked_keyword
    ,rs_impressed_keyword AS fe_module_impressed_keyword
    ,ai_minifeed_card_title
    ,llm_rewrite_keyword
    ,fe_module_title
    ,GET_JSON_OBJECT(ai_search_info, '$.md5') AS ms_image_url
    ,GET_JSON_OBJECT(ai_search_info, '$.box.box_xy') AS ms_image_bounding_box
    ,search_mid
    ,search_entrance
    ,CAST(GET_JSON_OBJECT(ai_search_info, '$.minifeed_ui_type') AS INT) AS minifeed_ui_type
    ,CAST(GET_JSON_OBJECT(ai_search_info, '$.click_area') AS INT) AS click_area
    
    ,GET_JSON_OBJECT(ai_search_info, '$.mm_search_intent_type') AS mm_search_intent_type
    ,image_id
    ,title_text
    ,content_id
    ,operation
    ,operation_cnt
    ,place_order_gmv AS gmv
    ,pc2_gmv
FROM
    srdi_mart.dwd_sr_data_warehouse_platform
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND user_id > 0
    AND page_type IN ('global_search','search_in_pdp','search_prefill')
    AND (
        (page_section IS NULL AND target_type IN ('item', 'video', 'livestream', 'related_search', 'ai_minifeed_card', 'ai_topic_card'))
        OR page_section IS NULL
    )
    AND (
        operation IN ('impression', 'order')
        OR (operation = 'click' AND original_operation IN ('click', 'action_aimode_item_rnd', 'action_see_more', 'action_dismiss', 'action_received_all_info', 'action_render_all_info'))
    )
    AND (
        is_llm_deepthinking = TRUE -- [Deepthinking]
        OR ARRAY_CONTAINS(TRANSFORM(search_filter_string, x -> FROM_JSON(x,'STRUCT<filter_type:INT>').filter_type), 3) -- [LLM Filter]
        OR rs_is_llm_card = TRUE -- [related_search]
        OR search_session_id IN (SELECT search_session_id FROM autocomplete_filter_${grass_region_without_quote}) -- [autocomplete]
        OR target_type IN ('ai_minifeed_card', 'ai_topic_card')
        OR search_mid LIKE 'image%'
    )
UNION ALL
