-- [AI minifeed card] dwd data
CREATE TEMPORARY VIEW minifeed_data_${grass_region_without_quote} AS
SELECT
    user_id
    ,sv_source_request_id AS srp_request_id
    ,request_id AS inner_request_id
    ,item_id
    ,'video' AS page_type
    ,NULL AS page_section
    ,ELEMENT_AT(SPLIT(feature_detail, '-'), -1) AS target_type -- To accomodate 4 part order
    ,is_ads
    ,sv_source_location AS srp_location
    ,location AS inner_location
    ,search_session_id
    ,CASE
        WHEN content_type = 'item' THEN 'item_card'
        WHEN business_id = '1003' THEN 'video_card'
        ELSE NULL
    END AS minifeed_inner_card_type
    ,operation
    ,operation_cnt
    ,place_order_gmv AS gmv
    ,pc2_gmv
FROM
    srdi_mart.dwd_sr_data_warehouse_platform
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND user_id > 0
    AND page_type = 'video'
    AND sv_source_page IN ('iaa_srp_ai_card', 'iaa_srp_hashtag_card')
    AND position_current_page IN ('srp_ai_card_page', 'hashtag_mix_feed_page')
    AND (
        (operation = 'click' AND original_operation = 'click' AND page_section IS NULL AND target_type IN ('video_product_click','atc_click','buynow_click'))
        OR (operation = 'impression' AND page_section IS NULL AND target_type IN ('video_product_impression'))
        OR (operation = 'order' AND page_section IS NULL AND target_type IN ('video_product_click','atc_click','buynow_click'))
        OR (operation = 'order' AND page_section[0] IN ('srp_ai_card_page', 'hashtag_mix_feed_page') AND target_type = 'anchor_product')
        -- For order, need to include video feature_detail with 4 parts, example: video-hashtag_mix_feed_page-anchor_product-video_product_click
        -- dwd_platform table target_type extraction is hardcoded at array position 2
    )
UNION ALL
--dwd_platform's S1/S2 feature_detail is not directly from omni table but a calculated 3 part concat
