    user_id
    ,source1_sv_source_request_id AS srp_request_id
    ,source1_request_id AS inner_request_id
    ,CAST(source1_ext_item_id AS BIGINT) AS item_id
    ,'video' AS page_type
    ,NULL AS page_section
    ,ELEMENT_AT(SPLIT(source1_feature_detail, '-'), -1) AS target_type -- To accomodate 4 part order
    ,source1_is_ads AS is_ads
    ,source1_sv_source_location AS srp_location
    ,source1_location AS inner_location
    ,source1_search_session_id AS search_session_id
    ,CASE
        WHEN source1_content_type = 'item' THEN 'item_card'
        WHEN source1_business_id = '1003' THEN 'video_card'
        ELSE NULL
    END AS minifeed_inner_card_type
    ,operation
    ,operation_cnt
    ,place_order_gmv AS gmv
    ,pc2_gmv
FROM
    srdi_mart.dwd_sr_data_warehouse_platform
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND user_id > 0
    AND operation = 'order' 
    AND source1_page_type = 'video'
    AND source1_sv_source_page IN ('iaa_srp_ai_card', 'iaa_srp_hashtag_card')
    AND source1_position_current_page IN ('srp_ai_card_page', 'hashtag_mix_feed_page')
    AND (
        (source1_page_section IS NULL AND source1_target_type IN ('video_product_click','atc_click','buynow_click'))
        OR (source1_page_section[0] IN ('srp_ai_card_page', 'hashtag_mix_feed_page') AND source1_target_type = 'anchor_product')
        -- For order, need to include video feature_detail with 4 parts, example: video-hashtag_mix_feed_page-anchor_product-video_product_click
        -- dwd_platform table target_type extraction is hardcoded at array position 2
    ) 
UNION ALL
SELECT
