SELECT
    user_id
    ,request_id AS inner_request_id
    ,item_id
    ,'ai_topic_landing' AS page_type
    ,'topic_result' AS page_section
    ,target_type
    ,location AS inner_location
    ,is_ads
    ,search_session_id
    ,global_session_id
    ,keyword
    ,topic_title
    ,topic_location
    ,ai_topic_srp_location
    ,ai_topic_srp_title
    ,search_mid
    ,search_entrance
    ,operation
    ,operation_cnt
    ,place_order_gmv AS gmv
    ,pc2_gmv
FROM
    srdi_mart.dwd_sr_data_warehouse_platform
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND user_id > 0
    AND (page_type = 'ai_topic_landing' OR original_page_type = 'ai_topic_landing')
    AND page_section[0] = 'topic_result'
    AND (
        (operation = 'click' AND original_operation = 'click' AND target_type IN ('item', 'add_to_cart_button'))
        OR (operation = 'impression' AND target_type = 'item')
        OR (operation = 'order' AND target_type IN ('item', 'add_to_cart_button'))
    )
UNION ALL
